retry.response:
#output-format:application/sparql-results+json
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorName ?birthDate WHERE {
  VALUES (?film ?filmLabel) {
    (<http://dbpedia.org/resource/My_Baby's_Daddy> "My Baby's Daddy")
    (<http://dbpedia.org/resource/A_Tale_of_Winter> "A Tale of Winter")
  }
  OPTIONAL { ?film dbo:director ?dir1 . }
  OPTIONAL { ?film dbp:director ?dir2 . }
  BIND(COALESCE(?dir1, ?dir2) AS ?director)
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL {
    ?director rdfs:label ?directorName .
    FILTER (lang(?directorName) = "en")
  }
}
ORDER BY DESC(?birthDate)
LIMIT 1

